mapper.select:
SELECT noti_id, receiver_mid, sender_mid, noti_type,
       ref_id, message, is_read, reg_date
FROM notification
WHERE noti_id = #{notiId}
  AND receiver_mid = #{receiverMid}

mapper.update:
UPDATE notification
SET is_read = 1
WHERE noti_id = #{notiId}
  AND receiver_mid = #{receiverMid}
